// src/lib/mcp/tools/list_projects.ts
var list_projects_default = defineTool({
  name: "list_projects",
  title: "List projects",
  description: "List every automation case study VIVIFY has shipped. Returns id, title, tag, one-line summary, and tech stack for each.",
  inputSchema: {
    stack: z.string().optional().describe("Optional tech to filter by, e.g. 'n8n', 'Gemini', 'VAPI'.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ stack }) => {
    const filtered = stack ? projects.filter(
      (p) => p.stack.some((s) => s.toLowerCase().includes(stack.toLowerCase()))
    ) : projects;
    const rows = filtered.map((p) => ({
      id: p.id,
      title: p.title,
      tag: p.tag,
      summary: p.summary,
      stack: p.stack
    }));
    return {
      content: [{ type: "text", text: JSON.stringify(rows, null, 2) }],
      structuredContent: { count: rows.length, projects: rows }
    };
  }
});

// src/lib/mcp/tools/get_project.ts
import { defineTool as defineTool2 } from "npm:@lovable.dev/mcp-js@0.23.0";
import { z as z2 } from "npm:zod@^4.4.3";
var get_project_default = defineTool2({
  name: "get_project",
  title: "Get project case study",
  description: "Return the full case study (problem, solution, result, stack) for one VIVIFY project by id. Use list_projects first to discover ids.",
  inputSchema: {
    id: z2.string().min(1).describe("Project id from list_projects, e.g. 'fb-messenger-agent'.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ id }) => {
    const p = projects.find((x) => x.id === id);
    if (!p) {
      return {
        content: [{ type: "text", text: `No project with id "${id}". Call list_projects to see valid ids.` }],
        isError: true
      };
    }
    return {
      content: [{ type: "text", text: JSON.stringify(p, null, 2) }],
      structuredContent: { project: p }
    };
  }
});

